"""mpl_toolkits.axes_grid1.axes_size — size helpers."""

from mpl_toolkits.axes_grid1.axes_divider import Size

Fixed = Size.Fixed
Scaled = Size.Scaled
AxesX = Size.AxesX
AxesY = Size.AxesY
Fraction = Size.Fraction
Padded = Size.Padded
from_any = Size.from_any

class MaxExtent:
    """Size descriptor whose value tracks the maximum width or height
    across a list of artists. Used by axes_divider when one cell must
    be sized to fit the widest legend / colorbar / etc."""

    def __init__(self, artist_list, w_or_h):
        if w_or_h not in ('width', 'height'):
            raise ValueError(f"w_or_h must be 'width' or 'height', got {w_or_h!r}")
        self._artists = list(artist_list)
        self._w_or_h = w_or_h

    def get_size(self, renderer=None):
        """Return ``(rel_size, abs_size)`` — the divider expects this.
        We compute the max across the artist list's window extents."""
        import numpy as _np
        max_v = 0.0
        for a in self._artists:
            try:
                bb = a.get_window_extent(renderer)
                if bb is None: continue
                v = bb.width if self._w_or_h == 'width' else bb.height
                max_v = max(max_v, float(v))
            except Exception:
                pass
        return (0.0, max_v / 72.0)  # absolute size in inches at 72dpi


class MaxWidth(MaxExtent):
    def __init__(self, artist_list):
        super().__init__(artist_list, 'width')


class MaxHeight(MaxExtent):
    def __init__(self, artist_list):
        super().__init__(artist_list, 'height')


class SizeFromFunc:
    """A size descriptor whose value is computed by a user-supplied
    callable ``func(renderer)``."""

    def __init__(self, func):
        self._func = func

    def get_size(self, renderer=None):
        try:
            v = self._func(renderer)
        except Exception:
            v = 0.0
        # Allow the callable to return either a scalar (treated as
        # absolute size) or a (rel, abs) tuple.
        if isinstance(v, tuple) and len(v) == 2:
            return float(v[0]), float(v[1])
        return (0.0, float(v))


