class _Base:
    """Base class for size descriptors used by the axes_grid layout."""
    def __init__(self, value=1):
        self.value = value

    def get_size(self, renderer=None):
        # Returns ``(rel_size, abs_size)`` — the divider expects this
        # tuple. The shim uses identity (relative-only) sizing.
        return float(self.value), 0.0

    def __add__(self, other):
        if isinstance(other, _Base):
            return Add(self, other)
        return Add(self, _Base(other))


class Add(_Base):
    """Sum of two size descriptors."""

    def __init__(self, a, b):
        super().__init__()
        self.a, self.b = a, b

    def get_size(self, renderer=None):
        ra, aa = self.a.get_size(renderer)
        rb, ab = self.b.get_size(renderer)
        return ra + rb, aa + ab


class Scalable(_Base):
    """A size that scales proportionally with the parent axes."""

    def __init__(self, value=1):
        super().__init__(value)

    def get_size(self, renderer=None):
        return float(self.value), 0.0
